class Solution {
public:
    string simplifyPath(string path) {
        vector<string> st;
        int i = 0, n = path.size();
        while (i < n) {
            while (i < n && path[i] == '/') i++;
            string name;
            while (i < n && path[i] != '/') name.push_back(path[i++]);
            if (name.empty() || name == ".") continue;
            if (name == "..") {
                if (!st.empty()) st.pop_back();
            } else {
                st.push_back(name);
            }
        }
        string res;
        for (auto& s : st) res += "/" + s;
        return res.empty() ? "/" : res;
    }
};
